const body=document.body,toast=document.querySelector('.toast'),empty=document.querySelector('.empty');
const states={importing:['Importing evidence: release-evidence.pdf · 62%.','normal'],oversize:['Attachment rejected: 54 MB is larger than the 25 MB meeting limit.','error'],generating:['Generating a decision artifact locally. No provider request is made.','normal'],success:['Decision artifact generated and placed on the shared table.','normal'],failure:['Definite provider failure: authentication was rejected before generation started.','error'],unknown:['Outcome unknown: the provider may have received the request. Automatic replay is disabled.','warning'],cancelled:['Operation cancelled. The meeting remains unchanged.','normal']};
function show(text,kind='normal'){toast.textContent=text;toast.dataset.kind=kind;toast.hidden=false}function setState(value){body.dataset.state=value;empty.hidden=value!=='empty';document.querySelector('#table .title-row').hidden=value==='empty';document.querySelector('.tabletop').hidden=value==='empty';document.querySelector('.below').hidden=value==='empty';if(states[value])show(...states[value]);else toast.hidden=true}
document.querySelector('#state').addEventListener('change',e=>setState(e.target.value));document.querySelectorAll('[data-mode-button]').forEach(b=>b.addEventListener('click',()=>{const id=b.dataset.modeButton;body.dataset.mode=id;document.querySelectorAll('.mode').forEach(x=>x.hidden=x.id!==id);document.querySelectorAll('.rail [data-mode-button]').forEach(x=>x.classList.toggle('active',x.dataset.modeButton===id))}));document.querySelectorAll('[data-dialog]').forEach(b=>b.addEventListener('click',()=>document.getElementById(b.dataset.dialog).showModal()));document.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>{const a=b.dataset.action;if(a==='generate')setState('generating');if(a==='import')setState('importing');if(a==='send')show('Guidance added to the local meeting transcript.')}));document.querySelector('#new').addEventListener('close',()=>{if(document.querySelector('#new').returnValue==='default'){setState('new');show('New meeting table created with fake data.')}});
